package lima

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
)

// qemuWrapperHead and qemuWrapperTail surround the shell-quoted path of the real QEMU.
const (
	qemuWrapperHead = `#!/usr/bin/env bash
# Generated by kubelab; do not edit. Lima connects user-v2 VMs with QEMU's legacy
# socket netdev, which aborts on io_uring builds (net_fill_rstate: Assertion
# 'size == 0' failed; https://github.com/lima-vm/lima/issues/5722). Use the
# equivalent stream netdev instead; every other argument is passed through.
args=()
prev=
for a in "$@"; do
  if [[ $prev == -netdev && $a =~ ^socket,id=([^,]+),fd=([0-9]+)$ ]]; then
    a="stream,id=${BASH_REMATCH[1]},addr.type=fd,addr.str=${BASH_REMATCH[2]}"
  fi
  args+=("$a")
  prev=$a
done
exec `
	qemuWrapperTail = ` "${args[@]}"
`
)

// UseQEMUStreamNetdev makes every limactl started by this process run QEMU through
// a wrapper that avoids the user-v2 crash described in qemuWrapperHead. It only
// applies on Linux, and leaves a QEMU chosen through Lima's environment variable alone.
func UseQEMUStreamNetdev(stateDir string) error {
	if runtime.GOOS != "linux" {
		return nil
	}
	arch := qemuArch()
	if arch == "" {
		return nil
	}
	envVar := "QEMU_SYSTEM_" + strings.ToUpper(arch)
	if os.Getenv(envVar) != "" {
		return nil
	}
	name := "qemu-system-" + arch
	found, err := exec.LookPath(name)
	if err != nil {
		return nil // limactl reports a missing QEMU better than we could
	}
	real, err := filepath.Abs(found)
	if err != nil {
		return err
	}
	if real, err = filepath.EvalSymlinks(real); err != nil {
		return err
	}

	dir := filepath.Join(stateDir, "qemu")
	if err := os.MkdirAll(filepath.Join(dir, "bin"), 0o755); err != nil {
		return err
	}
	// Lima looks for firmware relative to the QEMU binary, so mirror the real prefix.
	share := filepath.Join(filepath.Dir(filepath.Dir(real)), "share")
	if err := ensureSymlink(share, filepath.Join(dir, "share")); err != nil {
		return err
	}
	wrapper := filepath.Join(dir, "bin", name)
	script := []byte(qemuWrapperHead + shellQuote(real) + qemuWrapperTail)
	if err := writeExecutable(wrapper, script); err != nil {
		return err
	}
	return os.Setenv(envVar, wrapper)
}

func qemuArch() string {
	switch runtime.GOARCH {
	case "amd64":
		return "x86_64"
	case "arm64":
		return "aarch64"
	}
	return ""
}

func ensureSymlink(target, link string) error {
	if cur, err := os.Readlink(link); err == nil && cur == target {
		return nil
	}
	tmp := fmt.Sprintf("%s.%d", link, os.Getpid())
	os.Remove(tmp)
	if err := os.Symlink(target, tmp); err != nil {
		return err
	}
	return os.Rename(tmp, link)
}

// writeExecutable replaces path atomically, because another kubelab may be starting VMs.
func writeExecutable(path string, data []byte) error {
	if cur, err := os.ReadFile(path); err == nil && bytes.Equal(cur, data) {
		return nil
	}
	tmp := fmt.Sprintf("%s.%d", path, os.Getpid())
	if err := os.WriteFile(tmp, data, 0o755); err != nil {
		return err
	}
	if err := os.Chmod(tmp, 0o755); err != nil {
		os.Remove(tmp)
		return err
	}
	return os.Rename(tmp, path)
}
